def kruskal_mst(n, edges)
  edges = edges.sort_by { |e| e[2] }
  dsu = DSU.new(n)
  total = 0
  cnt = 0
  edges.each do |u,v,w|
    if dsu.unite(u,v)
      total += w
      cnt += 1
      break if cnt == n-1
    end
  end
  cnt == n-1 ? total : -1
end

class DSU
  def initialize(n)
    @p = (0...n).to_a
    @r = Array.new(n, 0)
  end
  def find(x)
    @p[x] = find(@p[x]) if @p[x] != x
    @p[x]
  end
  def union(a,b)
    a = find(a); b = find(b)
    return false if a == b
    if @r[a] < @r[b]
      a, b = b, a
    end
    @p[b] = a
    @r[a] += 1 if @r[a] == @r[b]
    true
  end
  def same(a,b)
    find(a) == find(b)
  end
end

